mapper.update:
UPDATE forbidden_word
SET word = #{word},
    replacement = #{replacement},
    description = #{description}
WHERE id = #{id, jdbcType=OTHER}

UPDATE standard_word
SET logical_name = #{logicalName},
    physical_name = #{physicalName},
    domain_id = #{domainId, jdbcType=OTHER},
    description = #{description}
WHERE id = #{id, jdbcType=OTHER}

UPDATE standard_term
SET logical_name = #{logicalName},
    physical_name = #{physicalName},
    description = #{description},
    word_ids = #{wordIds}
WHERE id = #{id, jdbcType=OTHER}
